#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    size_t capacity;
    size_t size;
    size_t head;
    size_t tail;
    uint8_t *buf;
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;
    uint8_t *buf = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        goto fail;

    buf = malloc(capacity);
    if (!buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->size     = 0;
    rb->head     = 0;
    rb->tail     = 0;
    rb->buf      = buf;
    return rb;

fail:
    free(buf);
    free(rb);
    return NULL;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->size     = 0;
    rb->head     = 0;
    rb->tail     = 0;
}

static void bump(size_t *pos, size_t n, size_t mod)
{
    *pos = (*pos + n) % mod;
}

/* Returns number of bytes free in the ring buffer */
static size_t free_space(const ringbuf_t *rb)
{
    return rb->capacity - rb->size;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    /* How many bytes we can store at once (no wrap-around copy) */
    size_t chunk1 = rb->capacity - rb->tail;
    size_t space  = free_space(rb);
    size_t n;

    if ((size_t)(rb->capacity - rb->head) < len) {
        /* full ring, no room to advance tail up to head */
        return 0;
    }

    n = (len < space) ? len : space;
    if (n == 0)
        return 0;

    /* First linear chunk starting at tail */
    size_t c1 = ((n < chunk1) ? n : chunk1);
    if (data) {
        memcpy(rb->buf + rb->tail, data, c1);
    }

    /* Second wrap-around chunk if needed */
    if (n > c1) {
        size_t c2 = n - c1;
        memcpy(rb->buf, data + c1, c2);
    }

    bump(&rb->tail, n, rb->capacity);
    rb->size += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->size == 0)
        return 0;

    size_t n = (len < rb->size) ? len : rb->size;
    size_t chunk1 = rb->capacity - rb->head;
    size_t c1 = ((n < chunk1) ? n : chunk1);

    if (out) {
        memcpy(out, rb->buf + rb->head, c1);
    }
    if (n > c1) {
        size_t c2 = n - c1;
        /* Wrap-around read */
        if (out) {
            memcpy(out + c1, rb->buf, c2);
        }
    }

    bump(&rb->head, n, rb->capacity);
    rb->size -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || len == 0)
        return 0;

    if (rb->size == 0)
        return 0;

    /* Use a temporary head for the peek */
    size_t tmp_head = rb->head;
    size_t n = (len < rb->size) ? len : rb->size;
    size_t chunk1 = rb->capacity - tmp_head;
    size_t c1 = ((n < chunk1) ? n : chunk1);
    size_t c2 = n - c1;

    if (out) {
        memcpy(out, rb->buf + tmp_head, c1);
        if (c2 > 0) {
            memcpy(out + c1, rb->buf, c2);
        }
    }
    return n;
}

